INSERT INTO lesson_visuals (id,lesson_id,title,image_url,alt_text,caption,display_order) VALUES ('740f6c41-e46f-44fe-8756-bb470f71703a','49cfab40-e211-50a7-8513-536c105dda4c','What Data Engineering Solves — Concept Visual','/content/courses/data-engineering/visuals/01-data-engineering-foundations/01-what-data-engineering-solves.svg','What Data Engineering Solves concept visual','Visual flow for What Data Engineering Solves. Use it to explain the concept before the hands-on exercise. ',0);
INSERT INTO lesson_practice (id,lesson_id,title,instructions,tasks_json,display_order,status) VALUES ('5ee06907-0703-4a64-8c7b-bc61fd304fdd','49cfab40-e211-50a7-8513-536c105dda4c','What Data Engineering Solves — Practice','Apply What Data Engineering Solves in a realistic Data Engineering scenario and explain the engineering trade-offs.','["Explain What Data Engineering Solves in your own words and identify the problem it solves.","Create a small example for What Data Engineering Solves using realistic input data.","Add at least three validation checks for correctness or edge cases.","Describe what should happen when input is missing, duplicated or malformed.","Prepare a two-minute interview explanation covering scale, reliability and cost."]',0,'published');
INSERT INTO course_quizzes (id,course_id,lesson_id,title,passing_percent,status) VALUES ('323af006-cb1d-4fd6-9bd6-52787bba710f',@course_id,'49cfab40-e211-50a7-8513-536c105dda4c','What Data Engineering Solves — Concept Check',70,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('01e8cbe9-e1cd-4efb-956c-f74aa0846f22','323af006-cb1d-4fd6-9bd6-52787bba710f','Which approach best demonstrates a production-ready understanding of What Data Engineering Solves?','["A working example with inputs, outputs, validation and failure handling","Only memorizing syntax or definitions","Running one happy-path example without validation","Copying a code snippet without explaining it"]',0,'Industry-ready implementation includes correctness, validation and operational behavior.','EASY',0,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('196342db-82ce-4de8-8fa0-b4d17b9270bb','323af006-cb1d-4fd6-9bd6-52787bba710f','When applying What Data Engineering Solves, which concern should be considered before production release?','["Correctness, scale, failure handling and observability","Only the UI color scheme","Only the number of lines of code","Only whether the first run succeeds"]',0,'Production engineering requires correctness plus operational and scale considerations.','EASY',1,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('8ccfc064-3446-44f3-ab2d-a26887c0b07b','323af006-cb1d-4fd6-9bd6-52787bba710f','What should you be able to explain in an interview about What Data Engineering Solves?','["Why it is used, how it works, trade-offs and failure modes","Only the command used to run it","Only a textbook definition","Only the library name"]',0,'Strong engineering answers connect implementation details to business and operational trade-offs.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('784d6ea5-2912-4912-8b2e-4789f2447737','323af006-cb1d-4fd6-9bd6-52787bba710f','What is a useful validation technique for What Data Engineering Solves?','["Test representative inputs, edge cases and expected outputs","Skip validation because production data is trusted","Validate only after a failure occurs","Check only that the process started"]',0,'Validation should prove expected behavior before the solution is relied upon.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('05990d8b-26a3-40a9-974b-a50b1a6b62e7','323af006-cb1d-4fd6-9bd6-52787bba710f','What is the safest way to handle a retry while implementing What Data Engineering Solves?','["Make the operation deterministic/idempotent where possible and observe failures","Assume every retry is harmless","Create duplicate outputs intentionally","Disable logging to reduce noise"]',0,'Safe retries depend on predictable effects, idempotency and observability.','HARD',4,'published');
