INSERT INTO lesson_practice (id,lesson_id,title,instructions,tasks_json,display_order,status) VALUES ('11de5cbe-f0ac-4b29-9fd4-bf9469229caf','808b4d4e-b58b-55b3-bcd5-d78793ff1189','Medallion Architecture and Data Lifecycle — Practice','Apply Medallion Architecture and Data Lifecycle in a realistic Data Engineering scenario and explain the engineering trade-offs.','["Explain Medallion Architecture and Data Lifecycle in your own words and identify the problem it solves.","Create a small example for Medallion Architecture and Data Lifecycle using realistic input data.","Add at least three validation checks for correctness or edge cases.","Describe what should happen when input is missing, duplicated or malformed.","Prepare a two-minute interview explanation covering scale, reliability and cost."]',0,'published');
