INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('0611cde3-d5b8-4c54-ab64-bd3603783bec','a80294fc-f2e7-4cda-a4c0-8ca6820837bd','Which approach best demonstrates a production-ready understanding of Medallion Architecture and Data Lifecycle?','["A working example with inputs, outputs, validation and failure handling","Only memorizing syntax or definitions","Running one happy-path example without validation","Copying a code snippet without explaining it"]',0,'Industry-ready implementation includes correctness, validation and operational behavior.','EASY',0,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('e45c6a39-9f51-45cc-a4a9-d04eb8e80c83','a80294fc-f2e7-4cda-a4c0-8ca6820837bd','When applying Medallion Architecture and Data Lifecycle, which concern should be considered before production release?','["Correctness, scale, failure handling and observability","Only the UI color scheme","Only the number of lines of code","Only whether the first run succeeds"]',0,'Production engineering requires correctness plus operational and scale considerations.','EASY',1,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('3855a922-cab6-4119-885c-bfd8fd5a064a','a80294fc-f2e7-4cda-a4c0-8ca6820837bd','What should you be able to explain in an interview about Medallion Architecture and Data Lifecycle?','["Why it is used, how it works, trade-offs and failure modes","Only the command used to run it","Only a textbook definition","Only the library name"]',0,'Strong engineering answers connect implementation details to business and operational trade-offs.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('3312bd90-2188-4ffb-9618-370033955b60','a80294fc-f2e7-4cda-a4c0-8ca6820837bd','What is a useful validation technique for Medallion Architecture and Data Lifecycle?','["Test representative inputs, edge cases and expected outputs","Skip validation because production data is trusted","Validate only after a failure occurs","Check only that the process started"]',0,'Validation should prove expected behavior before the solution is relied upon.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('0eae8516-8cf8-45de-911e-81cb74c47dc9','a80294fc-f2e7-4cda-a4c0-8ca6820837bd','What is the safest way to handle a retry while implementing Medallion Architecture and Data Lifecycle?','["Make the operation deterministic/idempotent where possible and observe failures","Assume every retry is harmless","Create duplicate outputs intentionally","Disable logging to reduce noise"]',0,'Safe retries depend on predictable effects, idempotency and observability.','HARD',4,'published');
