INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('ec1d52a6-0c7c-4563-9388-bd3c97f3fe33','b3edfc6c-7b67-4268-9735-bd3da3bd608e','What is the purpose of ORDER BY inside OVER(...)?','["Defines row ordering used by the window calculation","Sorts the entire table permanently","Creates an index automatically","Filters rows before the query runs"]',0,'The window ORDER BY defines the logical row sequence for functions such as ROW_NUMBER and running totals.','EASY',1,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('0598a3cf-cbe6-47d9-9d03-657503d7f160','b3edfc6c-7b67-4268-9735-bd3da3bd608e','Which function assigns a unique sequential number even when salaries tie?','["ROW_NUMBER()","RANK()","DENSE_RANK()","COUNT()"]',0,'ROW_NUMBER assigns a distinct sequence number to each row.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('ef61a2dd-05b3-4798-96bd-f1701d3aa974','b3edfc6c-7b67-4268-9735-bd3da3bd608e','Which pattern is appropriate for a running total?','["SUM(amount) OVER (ORDER BY order_date)","SUM(amount) GROUP BY order_date","COUNT(*) WHERE order_date","AVG(amount) DISTINCT"]',0,'A windowed SUM with an ORDER BY can calculate a running total while preserving row detail.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('dd4272e7-1aca-49fa-94fe-583bc3741f86','b3edfc6c-7b67-4268-9735-bd3da3bd608e','Why are window functions useful in analytical SQL?','["They calculate across related rows without collapsing the result to one row per group","They replace every JOIN","They remove the need for indexes","They only work for OLTP workloads"]',0,'Window functions add analytical calculations while retaining row-level detail.','HARD',4,'published');
INSERT INTO course_assignments (id,course_id,lesson_id,title,instructions,submission_type,status) VALUES ('e03f9282-9987-461f-aad5-0b53ac35e9c4',@course_id,'aef1386b-e59f-5b67-ac3e-3c1078dc2059','Window Functions and Analytical SQL — Industry Assignment','Build a small production-style implementation for Window Functions and Analytical SQL. Apply Window Functions and Analytical SQL in a realistic Data Engineering scenario and explain the engineering trade-offs. Submit the source/design, sample input and output, validation evidence, assumptions and failure-handling notes.
INSERT INTO lesson_labs (id,lesson_id,lab_type,title,external_url,instructions,dataset_url,config_json,display_order) VALUES ('ff0be31f-db15-4142-985e-fcc6cc27027b','aef1386b-e59f-5b67-ac3e-3c1078dc2059','SQL','Window Functions and Analytical SQL — Hands-on Lab',NULL,'Hands-on Window Functions and Analytical SQL lab. Apply Window Functions and Analytical SQL in a realistic Data Engineering scenario and explain the engineering trade-offs. Start with the provided example, implement the task, validate the result and document one failure scenario.','/content/courses/data-engineering/modules/03-sql-database-engineering/lab/lab.sql','{"focus":"partitioning, ordering, window frames and analytical calculations","starterSql":"SELECT department_id, name, salary, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY salary DESC) AS salary_rank FROM employees;"}',0);
