INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('4e323be8-8802-4290-bf85-09cd57fe8110','e248e179-9acf-4702-9f31-e69d2f64c101','Which approach best demonstrates a production-ready understanding of Python Runtime, Types and Core Syntax?','["A working example with inputs, outputs, validation and failure handling","Only memorizing syntax or definitions","Running one happy-path example without validation","Copying a code snippet without explaining it"]',0,'Industry-ready implementation includes correctness, validation and operational behavior.','EASY',0,'published');
