INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('859cd2ef-76d6-4a70-b142-f9bf17773ed4','6e6cd1a4-9358-4325-9b61-20467cf1b1ce','What is the purpose of ORDER BY inside OVER(...)?','["Defines row ordering used by the window calculation","Sorts the entire table permanently","Creates an index automatically","Filters rows before the query runs"]',0,'The window ORDER BY defines the logical row sequence for functions such as ROW_NUMBER and running totals.','EASY',1,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('2a0ae74f-b9f2-4146-9e9d-39602a4a6fc6','6e6cd1a4-9358-4325-9b61-20467cf1b1ce','Which function assigns a unique sequential number even when salaries tie?','["ROW_NUMBER()","RANK()","DENSE_RANK()","COUNT()"]',0,'ROW_NUMBER assigns a distinct sequence number to each row.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('256141f8-8a66-4e81-a534-ae9031e752df','6e6cd1a4-9358-4325-9b61-20467cf1b1ce','Which pattern is appropriate for a running total?','["SUM(amount) OVER (ORDER BY order_date)","SUM(amount) GROUP BY order_date","COUNT(*) WHERE order_date","AVG(amount) DISTINCT"]',0,'A windowed SUM with an ORDER BY can calculate a running total while preserving row detail.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('8c4a049d-909c-4ecc-a749-3e0154b3f117','6e6cd1a4-9358-4325-9b61-20467cf1b1ce','Why are window functions useful in analytical SQL?','["They calculate across related rows without collapsing the result to one row per group","They replace every JOIN","They remove the need for indexes","They only work for OLTP workloads"]',0,'Window functions add analytical calculations while retaining row-level detail.','HARD',4,'published');
