INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('be1fe97e-ec4e-4ad2-b412-ce38434774cd','78cb488e-1c4a-45f9-a29f-c8b17e77b24e','What does PARTITION BY do in a window function?','["Divides rows into logical groups for the window calculation","Deletes duplicate rows","Creates a physical database partition","Filters the final result"]',0,'PARTITION BY defines the logical groups over which the window calculation operates.','EASY',0,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('df903783-c877-42ea-8ea5-986fd9cfa1f1','78cb488e-1c4a-45f9-a29f-c8b17e77b24e','What is the purpose of ORDER BY inside OVER(...)?','["Defines row ordering used by the window calculation","Sorts the entire table permanently","Creates an index automatically","Filters rows before the query runs"]',0,'The window ORDER BY defines the logical row sequence for functions such as ROW_NUMBER and running totals.','EASY',1,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('70147270-51d9-4592-9f1b-75587fdb3d4e','78cb488e-1c4a-45f9-a29f-c8b17e77b24e','Which function assigns a unique sequential number even when salaries tie?','["ROW_NUMBER()","RANK()","DENSE_RANK()","COUNT()"]',0,'ROW_NUMBER assigns a distinct sequence number to each row.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('5345a23f-58d8-4f4d-beff-a0048028607d','78cb488e-1c4a-45f9-a29f-c8b17e77b24e','Which pattern is appropriate for a running total?','["SUM(amount) OVER (ORDER BY order_date)","SUM(amount) GROUP BY order_date","COUNT(*) WHERE order_date","AVG(amount) DISTINCT"]',0,'A windowed SUM with an ORDER BY can calculate a running total while preserving row detail.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('8e018f6a-7726-45f6-87e7-a3712e706972','78cb488e-1c4a-45f9-a29f-c8b17e77b24e','Why are window functions useful in analytical SQL?','["They calculate across related rows without collapsing the result to one row per group","They replace every JOIN","They remove the need for indexes","They only work for OLTP workloads"]',0,'Window functions add analytical calculations while retaining row-level detail.','HARD',4,'published');
