INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('07e85f92-500e-4ea2-a069-3f2e251a263c','eaf22ee9-09a5-4a78-8d0a-5362f5f85c34','Which approach best demonstrates a production-ready understanding of Pub/Sub Event Ingestion?','["A working example with inputs, outputs, validation and failure handling","Only memorizing syntax or definitions","Running one happy-path example without validation","Copying a code snippet without explaining it"]',0,'Industry-ready implementation includes correctness, validation and operational behavior.','EASY',0,'published');
