INSERT INTO lesson_practice (id,lesson_id,title,instructions,tasks_json,display_order,status) VALUES ('07485067-906a-48af-9ce4-ea55b173c63a','81afa502-89bb-50b4-a10d-113549e96456','Git Branching and Release Strategy — Practice','Apply Git Branching and Release Strategy in a realistic Data Engineering scenario and explain the engineering trade-offs.','["Explain Git Branching and Release Strategy in your own words and identify the problem it solves.","Create a small example for Git Branching and Release Strategy using realistic input data.","Add at least three validation checks for correctness or edge cases.","Describe what should happen when input is missing, duplicated or malformed.","Prepare a two-minute interview explanation covering scale, reliability and cost."]',0,'published');
