INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('829f57ee-0592-40a2-8c35-f11528b605f3','c2120058-4872-4abb-a0d1-b31e8be1290d','Which approach best demonstrates a production-ready understanding of Git Branching and Release Strategy?','["A working example with inputs, outputs, validation and failure handling","Only memorizing syntax or definitions","Running one happy-path example without validation","Copying a code snippet without explaining it"]',0,'Industry-ready implementation includes correctness, validation and operational behavior.','EASY',0,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('78aaf475-92d1-4754-a80f-02e176c48710','c2120058-4872-4abb-a0d1-b31e8be1290d','When applying Git Branching and Release Strategy, which concern should be considered before production release?','["Correctness, scale, failure handling and observability","Only the UI color scheme","Only the number of lines of code","Only whether the first run succeeds"]',0,'Production engineering requires correctness plus operational and scale considerations.','EASY',1,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('ddceb3ce-4b68-441b-a12a-dea6f7dd8e7f','c2120058-4872-4abb-a0d1-b31e8be1290d','What should you be able to explain in an interview about Git Branching and Release Strategy?','["Why it is used, how it works, trade-offs and failure modes","Only the command used to run it","Only a textbook definition","Only the library name"]',0,'Strong engineering answers connect implementation details to business and operational trade-offs.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('94e597ee-77dd-47d1-b2f9-5e2bbadac1ca','c2120058-4872-4abb-a0d1-b31e8be1290d','What is a useful validation technique for Git Branching and Release Strategy?','["Test representative inputs, edge cases and expected outputs","Skip validation because production data is trusted","Validate only after a failure occurs","Check only that the process started"]',0,'Validation should prove expected behavior before the solution is relied upon.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('3edcc230-fbd9-4921-9a1c-eff61979d175','c2120058-4872-4abb-a0d1-b31e8be1290d','What is the safest way to handle a retry while implementing Git Branching and Release Strategy?','["Make the operation deterministic/idempotent where possible and observe failures","Assume every retry is harmless","Create duplicate outputs intentionally","Disable logging to reduce noise"]',0,'Safe retries depend on predictable effects, idempotency and observability.','HARD',4,'published');
