INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('a965c4f1-1b89-4f0d-83eb-32db3877df80','8d92f6fb-2faf-483d-9ad1-67fab9b1fd2e','What should you be able to explain in an interview about Incident Management and Postmortems?','["Why it is used, how it works, trade-offs and failure modes","Only the command used to run it","Only a textbook definition","Only the library name"]',0,'Strong engineering answers connect implementation details to business and operational trade-offs.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('7db3cde4-1f23-496d-94ac-ca4f6cb3fc40','8d92f6fb-2faf-483d-9ad1-67fab9b1fd2e','What is a useful validation technique for Incident Management and Postmortems?','["Test representative inputs, edge cases and expected outputs","Skip validation because production data is trusted","Validate only after a failure occurs","Check only that the process started"]',0,'Validation should prove expected behavior before the solution is relied upon.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('19c441c9-bb1c-4809-85ec-c559d52a92a5','8d92f6fb-2faf-483d-9ad1-67fab9b1fd2e','What is the safest way to handle a retry while implementing Incident Management and Postmortems?','["Make the operation deterministic/idempotent where possible and observe failures","Assume every retry is harmless","Create duplicate outputs intentionally","Disable logging to reduce noise"]',0,'Safe retries depend on predictable effects, idempotency and observability.','HARD',4,'published');
