INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('44a6b210-4884-4cdb-a76a-64c0ecdd2b45','2f55e696-4d35-486d-92f4-39b8beaf6f2f','What should you be able to explain in an interview about Project Storytelling with STAR?','["Why it is used, how it works, trade-offs and failure modes","Only the command used to run it","Only a textbook definition","Only the library name"]',0,'Strong engineering answers connect implementation details to business and operational trade-offs.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('47f438ac-26cd-422a-a724-9d40d0b7c705','2f55e696-4d35-486d-92f4-39b8beaf6f2f','What is a useful validation technique for Project Storytelling with STAR?','["Test representative inputs, edge cases and expected outputs","Skip validation because production data is trusted","Validate only after a failure occurs","Check only that the process started"]',0,'Validation should prove expected behavior before the solution is relied upon.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('ae757082-aa66-461b-8ea9-39f0694e851d','2f55e696-4d35-486d-92f4-39b8beaf6f2f','What is the safest way to handle a retry while implementing Project Storytelling with STAR?','["Make the operation deterministic/idempotent where possible and observe failures","Assume every retry is harmless","Create duplicate outputs intentionally","Disable logging to reduce noise"]',0,'Safe retries depend on predictable effects, idempotency and observability.','HARD',4,'published');
INSERT INTO course_assignments (id,course_id,lesson_id,title,instructions,submission_type,status) VALUES ('a745f7d8-a3ea-457d-af81-39d561d97caa',@course_id,'c11cc4a7-23cc-574e-b404-f1944bfacad7','Project Storytelling with STAR — Industry Assignment','Build a small production-style implementation for Project Storytelling with STAR. Apply Project Storytelling with STAR in a realistic Data Engineering scenario and explain the engineering trade-offs. Submit the source/design, sample input and output, validation evidence, assumptions and failure-handling notes.
